const deepFreeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(deepFreeze);Object.freeze(value);}return value;};
deepFreeze(LT_BLADE_PROFILES);
export const ltBladeSource=id=>LT_BLADE_PROFILES[id]??null;
export const ltBladeSiblings=profile=>Object.values(LT_BLADE_PROFILES).filter(p=>p.equipmentId===profile.equipmentId);
export function ltBladeGripPolicy(profile){
 if(!ltBladeSource(profile?.modeId))return null;
 if(profile.damagePart==='hilt')return {grips:[],reason:'Удар гардой использует отдельную строку Brawling/DX; варианты хвата клинка к нему не применяются. LT65.'};
 const siblings=ltBladeSiblings(profile),twoHanded=siblings.some(p=>/[†‡]/u.test(p.stats.st??''));
 const thrust=siblings.some(p=>/^thr.*\s+(imp|cr)$/u.test(p.stats.damage));
 const fixed=['lt:katar','lt:large-katar','lt:pata'].includes(profile.modelId);
 const knife=['lt:balisong','lt:dagger','lt:katar','lt:kukri','lt:large-katar','lt:large-knife','lt:large-throwing-knife',
  'lt:long-knife','lt:main-gauche','lt:rondel-dagger','lt:small-knife','lt:small-throwing-knife','lt:stiletto','lt:haladie'].includes(profile.modelId);
 return {grips:['defensive',...(thrust&&!fixed?['reversed']:[]),...(!knife&&thrust?['tip']:[])],twoHanded,
  freeReverse:profile.modelId==='lt:haladie',
  reason:fixed?'Поперечная рукоять/перчатка: обычный обратный хват не подтверждён. LT57; MA111.':
   !thrust?'Обратный хват и хват за остриё не подтверждены: числовой Hook не устанавливает обычный укол и форму кончика. LT57; MA111.':null};
}
export function ltBladeTipDamage(profile){
 if(!ltBladeGripPolicy(profile)?.grips.includes('tip'))throw Error('Хват за остриё не подтверждён для этой конструкции.');
 return profile.point==='blunt'||/^thr.*\s+cr$/u.test(profile.stats.damage)||
  !ltBladeSiblings(profile).some(p=>/^thr.*\s+imp$/u.test(p.stats.damage))?'thr cr':'thr imp';
}
export function ltBladeHints(profile){
 const out=['Reach – справка о дистанции, не блокировка Attack. C – вплотную; * – смена длины требует Ready. LT64; B270.',
  'Parry – только подсказка: F – фехтование; U – нельзя парировать в ход атаки; No – парировать нельзя. Защиту выбирают вручную. LT64.'];
 if(ltBladeGripPolicy(profile)?.freeReverse)out.push('Haladie: выбор обычного/обратного хвата свободный, без смены оружия; −1 к навыку уже учтён. Pummeling невозможен. LT56.');
 else out.push('Смена хвата требует Ready; время и Grip Mastery учитывает игрок. MA102; MA109–112.');
 if(ltBladeGripPolicy(profile)?.reason)out.push(ltBladeGripPolicy(profile).reason);
 if(profile.modelId==='lt:balisong')out.push('Для открытия этого низкотехнологичного Balisong нужен Ready; Fast-Draw не открывает его автоматически. LT54.');
 if(['lt:estoc','lt:rondel-dagger','lt:stiletto','lt:katar','lt:large-katar'].includes(profile.modelId))out.push('При выборе щелей в доспехе уменьшить штраф на 2; цель и условие выбираются вручную. LT71[4].');
 if(['lt:katar','lt:large-katar'].includes(profile.modelId))out.push('Для Katar-рукояти допустимо лучшее Brawling/Karate Parry; защита и DR гарды учитываются вручную. LT57; LT71[6,12].');
 if(profile.modelId==='lt:pata')out.push('Pata имеет встроенную перчатку/гарду; DR руки учитывается вручную. LT57; LT71[6].');
 if(profile.modelId==='lt:shotel')out.push('Shotel: −2 к атаке уже учтён один раз. Противник получает −1 к Block/Parry вручную. LT62; LT65; LT71[7].');
 if(profile.modelId==='lt:khopesh')out.push('Hook: числовой урон указан в таблице; зацеп, обезоруживание и последствия выполняются вручную. LT54; LT57; LT65; LT71[2].');
 if(profile.damagePart==='hilt')out.push('Удар гардой: Brawling или DX. Бонус Brawling +1 за куб при изученном навыке DX+2 уже учитывается; качество и материал клинка не усиливают гарду. LT65; LT71[5]; B182.');
 else if(profile.modelId!=='lt:haladie')out.push('Pummeling – отдельная ручная процедура по MA111, не дополнительный универсальный режим Attack. Качество кромки к рукояти не применяется.');
 return out;
}
function setDamage(mode,expression){
 const m=/^(sw|thr)([+-]\d+)?(?:\(([\d.]+)\))?\s+(\S+)$/u.exec(expression);
 if(!m)throw Error('Invalid LT blade source Damage');
 mode.raw_calc={...mode.raw_calc,damage:expression};
 const value={...mode.stats.damage,st:m[1],type:m[4]};
 if(m[2])value.base=String(Number(m[2]));else delete value.base;
 if(m[3])value.armor_divisor=Number(m[3]);else delete value.armor_divisor;
 mode.stats.damage=value;
}
export function applyLTBladeSourceMode(mode,equipment,{snapshot=false}={}){
 const p=ltBladeSource(mode?.weapon_mode_id);
 if(!p||equipment?.source!=='LT'||equipment.equipment_id!==p.equipmentId)return mode;
 const before=p.sourceFieldsBefore;
 if(!snapshot||!before||[before.damage,p.stats.damage].includes(mode.raw_calc?.damage))setDamage(mode,p.stats.damage);
 for(const [key,field]of [['reach','reach'],['parry','parry'],['strength','st']])
  if(!snapshot||!before||[before[field],p.stats[field]].includes(mode.stats[key]))mode.stats[key]=p.stats[field];
 if(!snapshot||!before||[before.usage,p.usage].includes(mode.usage))mode.usage=p.usage;
 mode.lt_blade_contract={modelId:p.modelId,sourcePages:p.sourcePages,damagePart:p.damagePart,point:p.point??null};
 return mode;
}
export function projectLTBladeSourceData(book,data){
 if(book!=='weapons')return data;
 // Module-owned identities for a source-only physical Haladie; never claim a GCS identity.
 if(!data.equipment.some(e=>e.equipment_id==='eLTM21Haladie')){
  const template=data.equipment.find(e=>e.equipment_id==='e4Cqh4R-bWl7CS7dQ');
  if(template){const e=structuredClone(template);Object.assign(e,{equipment_id:'eLTM21Haladie',name:'Haladie',reference:'LT56',tech_level:null,
   local_notes:'Двуклинковый нож: свободный выбор обычного/обратного хвата; −1 к навыку. Не допускает Pummeling. LT56.',
   lt_blade_origin:'module-printed-source-overlay',modes:[]});
   for(const p of Object.values(LT_BLADE_PROFILES).filter(p=>p.equipmentId===e.equipment_id)){
    const mode=structuredClone(template.modes.find(m=>m.combat_type==='melee'&&m.raw_calc?.damage.startsWith(p.stats.damage.startsWith('sw')?'sw':'thr')));
    mode.weapon_mode_id=p.modeId;mode.usage=p.usage;e.modes.push(mode);
   }data.equipment.push(e);
  }
 }
 for(const e of data.equipment){
  for(const p of Object.values(LT_BLADE_PROFILES).filter(p=>p.equipmentId===e.equipment_id&&p.templateModeId))
   if(!e.modes.some(m=>m.weapon_mode_id===p.modeId)){
    const original=e.modes.find(m=>m.weapon_mode_id===p.templateModeId);
    if(original){const m=structuredClone(original);m.weapon_mode_id=p.modeId;m.usage=p.usage;e.modes.push(m);}
   }
  for(const mode of e.modes)applyLTBladeSourceMode(mode,e);
 }return data;
}
